functions.inputHostLifecycleWorkIsCleanup:
static bool inputHostLifecycleWorkIsCleanup(const std::string& reason) {
    return reason == "virtual-target-disabled" ||
        reason == "startup-owned-return" ||
        reason == "quarantine-endpoint-absent" ||
        reason == "frame-receipt-fault" ||
        reason.rfind("fault-stop:", 0) == 0;
}

functions.inputHostExitFenceBlocks:
static bool inputHostExitFenceBlocks(bool fenceRaised, const std::string& reason) {
    return fenceRaised && !inputHostLifecycleWorkIsCleanup(reason);
}

functions.inputHostRaiseExitFence:
static void inputHostRaiseExitFence(const char* trigger) {
    if (g_inputHostExitFence.exchange(true, std::memory_order_acq_rel)) return;
    unsigned long long dropped = 0;
    unsigned long long keptCleanup = 0, keptSlotCancellation = 0;
    std::string droppedReasons;
    {
        std::lock_guard<std::mutex> lock(g_inputHostLifecycleWorkMx);
        std::deque<std::string> kept;
        for (auto& item : g_inputHostLifecycleWorkQueue) {
            // Keep only an already queued slot-step so its serial owner can
            // cancel the in-memory plan. New slot work remains fence-rejected.
            if (inputHostLifecycleWorkIsCleanup(item)) {
                kept.push_back(item);
                ++keptCleanup;
                continue;
            }
            if (item == "slot0-handoff-step") {
                kept.push_back(item);
                ++keptSlotCancellation;
                continue;
            }
            ++dropped;
            if (droppedReasons.size() < 160) {
                if (!droppedReasons.empty()) droppedReasons += "|";
                droppedReasons += item;
            }
        }
        g_inputHostLifecycleWorkQueue.swap(kept);
        g_inputHostLifecycleWorkRequested.store(!g_inputHostLifecycleWorkQueue.empty(), std::memory_order_release);
    }
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "raised"},
        {"trigger", trigger ? trigger : "unknown"},
        {"droppedQueued", dropped},
        {"keptCleanupQueued", keptCleanup},
        {"keptSlotCancellationQueued", keptSlotCancellation},
        {"droppedReasons", droppedReasons},
        {"refusals", 0ULL},
        {"exitSessionId", g_exitSessionId}   // 批138：与退出/fan 行同 ID
    });
}

functions.inputHostResetExitFence:
static void inputHostResetExitFence(const char* owner) {
    const bool previousRaised = g_inputHostExitFence.exchange(false, std::memory_order_acq_rel);
    g_inputHostExitFenceRefusals.store(0, std::memory_order_release);
    g_inputHostExitFenceRefusalRows.store(0, std::memory_order_release);
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "reset"},
        {"previousRaised", previousRaised},
        {"owner", owner ? owner : "unknown"},
        {"refusals", 0ULL}
    });
}
